// Worker entry: the OpenNext fetch handler plus our Cron Trigger handler.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as openNext } from '../../.open-next/worker.js';
import { runScheduled } from './scheduled';

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from '../../.open-next/worker.js';

export default {
  fetch: openNext.fetch,
  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(runScheduled(controller.cron, new Date(controller.scheduledTime), env));
  },
} satisfies ExportedHandler<CloudflareEnv>;
